        "abstract": "In diesem Beispiel wurde nach \"Region\", \"Vertriebsmitarbeiter\" und \"Produkt \" einzeln mit =SORTIEREN(A2:A17) sortiert und über die Zellen F2, H2 und J2 kopiert.",
